enum Role { APPLICANT, APPROVER, ADMIN }
record Emp(long id, String name, Role role) {}
record Req(long applicantId, int amount) {}

// 業務ルール1〜3だけの簡易版(演習1で状態も含めた完全版を作る)
String canApprove(Emp e, Req r) {
    if (e.role() == Role.APPLICANT) return "× 承認者ではない";
    if (e.id() == r.applicantId()) return "× 自分の申請";
    if (r.amount() >= 100_000 && e.role() != Role.ADMIN) return "× 高額は管理者だけ";
    return "○ 承認できる";
}

List<Emp> people = List.of(
    new Emp(1, "ハル", Role.APPLICANT),
    new Emp(2, "モカ", Role.APPROVER),
    new Emp(3, "部長", Role.ADMIN));

// ここを変えてみよう:金額を 99_999 や 100_000 に、申請者を 2(モカ)や 3(部長)に
Req req = new Req(1, 120_000);

System.out.println("申請者ID=" + req.applicantId() + " / 金額=" + req.amount());
for (Emp e : people) {
    // 画面の sec:authorize はロールしか見ない
    boolean buttonShown = e.role() != Role.APPLICANT;
    System.out.printf("%-3s %-9s ボタン表示:%s サーバー判定:%s%n",
            e.name(), e.role(), buttonShown ? "あり" : "なし", canApprove(e, req));
}

// 承認くんの URL ルール(上から順に見て、最初に一致したもので決まる)
// prefix で簡略化しています。本物は Spring Security の requestMatchers
record Rule(String prefix, String need) {}

List<Rule> rules = new ArrayList<>(List.of(
    new Rule("/login", "permitAll"),
    new Rule("/approvals", "APPROVER/ADMIN"),
    new Rule("/requests/search", "APPROVER/ADMIN"),
    new Rule("/", "authenticated")));

// ここを変えてみよう:下の行のコメントを外し、広いルールを先頭に入れて再実行
// rules.add(0, new Rule("/requests", "authenticated"));

String judge(String path, String role) {
    for (Rule r : rules) {
        if (!path.startsWith(r.prefix())) continue;
        if (r.need().equals("permitAll")) return "通す";
        if (role == null) return "→ /login";
        if (r.need().equals("authenticated")) return "通す";
        return r.need().contains(role) ? "通す" : "403";
    }
    return role == null ? "→ /login" : "403";
}

String[] paths = {"/login", "/requests", "/requests/search", "/approvals"};
String[] roles = {null, "APPLICANT", "APPROVER"};
for (String p : paths) {
    List<String> cells = new ArrayList<>();
    for (String role : roles) {
        cells.add((role == null ? "未ログイン" : role) + "=" + judge(p, role));
    }
    System.out.println(p + " → " + cells);
}

